-- =============================================================================
-- Finova Onboarding · Tuần 2 · Dữ liệu raw (mô phỏng) · schema hv04_source
-- 5 bảng giữ đúng cột của tuần 1 + 2 bảng mới: cash_txn, position_daily.
-- Chạy: psql -v ON_ERROR_STOP=1 -f w3_raw_hv04_source.sql   (hoặc mở trong DBeaver, Execute Script)
-- Sinh bằng gen_w3_data.py, seed 20261005. Không phải dữ liệu khách hàng thật.
-- =============================================================================
\encoding UTF8
set client_encoding = 'UTF8';
drop schema if exists hv04_source cascade;
create schema hv04_source;

create table hv04_source.branches (
  branch_code  text primary key,
  branch_name  text not null,
  parent_code  text
);
create table hv04_source.customers (            -- mỗi dòng là một phiên bản của khách hàng
  customer_id  text not null,
  segment      text not null,
  kyc_status   text not null,
  updated_at   date not null
);
create table hv04_source.accounts (
  account_id   text primary key,
  customer_id  text not null,
  branch_code  text not null,
  account_type text not null,
  open_date    date not null
);
create table hv04_source.instruments (
  symbol          text primary key,
  instrument_name text not null,
  exchange        text not null,
  sector          text not null,
  listing_date    date not null
);
create table hv04_source.orders (
  order_id   text primary key,
  account_id text not null,
  symbol     text not null,
  side       char(1) not null,          -- B mua, S bán
  quantity   integer not null,
  price      numeric(18,2) not null,    -- đồng/cổ phiếu
  order_ts   timestamptz not null,
  status     text not null              -- Filled, Partial, Cancelled, Rejected
);
create table hv04_source.cash_txn (         -- MỚI: giao dịch tiền; amount luôn dương, chiều theo txn_type
  txn_id       text primary key,
  account_id   text not null,
  txn_ts       timestamptz not null,
  txn_type     text not null,           -- DEPOSIT, WITHDRAW, BUY_SETTLE, SELL_SETTLE, FEE, TAX_SELL
  amount       numeric(20,2) not null,
  ref_order_id text                     -- lệnh gốc với FEE, TAX_SELL, *_SETTLE
);
create table hv04_source.position_daily (   -- MỚI: số dư chứng khoán cuối ngày, chỉ có dòng khi total_qty > 0
  snapshot_date date not null,
  account_id    text not null,
  symbol        text not null,
  total_qty     integer not null,       -- tổng khối lượng sở hữu
  receiving_qty integer not null,       -- khối lượng mua đang chờ về
  close_price   numeric(18,2) not null, -- giá tham chiếu cuối ngày (mô phỏng)
  primary key (snapshot_date, account_id, symbol)
);
